import passwordsText from './common-passwords.txt?raw';
import wordsText from './common-words.txt?raw';
import type { PasswordLists } from './strength';

// Generated by tools/passwords/update-common-passwords.sh from breach data (SecLists, MIT; see the About page).
// Loaded on demand: the lists are about 30 KB gzip and only the forms that set a password need them.
export const passwordLists: PasswordLists = {
  passwords: new Set(passwordsText.split('\n').filter((line) => line !== '')),
  words: new Map(
    wordsText
      .split('\n')
      .filter((line) => line !== '')
      .map((word, rank) => [word, rank]),
  ),
};
